package domain_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"servicetopology/backend/internal/domain"
	"servicetopology/backend/internal/fixtures"
)

// The Go validator must return the same issues, in the same order, as the TypeScript reference
// (fixtures generated by apps/web/src/contract/fixtures.test.ts).
func TestValidationConformance(t *testing.T) {
	dir, err := fixtures.Dir()
	if err != nil {
		t.Fatal(err)
	}
	files, err := filepath.Glob(filepath.Join(dir, "conformance", "validation", "*.json"))
	if err != nil {
		t.Fatal(err)
	}
	if len(files) < 20 {
		t.Fatalf("expected the full conformance set, found %d files in %s", len(files), dir)
	}
	for _, file := range files {
		t.Run(filepath.Base(file), func(t *testing.T) {
			raw, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}
			var c fixtures.ValidationCase
			if err := fixtures.DecodeStrict(raw, &c); err != nil {
				t.Fatalf("decode: %v", err)
			}
			got := []fixtures.ExpectedIssue{}
			for _, issue := range domain.Validate(&c.Topology) {
				got = append(got, fixtures.ExpectedIssue{Severity: issue.Severity, Code: issue.Code, EntityID: issue.EntityID})
			}
			want := c.Expected
			if want == nil {
				want = []fixtures.ExpectedIssue{}
			}
			if !reflect.DeepEqual(got, want) {
				t.Errorf("%s\n got: %+v\nwant: %+v", c.Description, got, want)
			}
		})
	}
}

func loadMock(t *testing.T) (*domain.TopologyData, []byte) {
	t.Helper()
	dir, err := fixtures.Dir()
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, "topology", "mock.v1.json")
	data, err := fixtures.LoadTopology(path)
	if err != nil {
		t.Fatal(err)
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return data, raw
}

func TestMockTopologyIsValid(t *testing.T) {
	data, _ := loadMock(t)
	if issues := domain.Validate(data); len(issues) != 0 {
		t.Fatalf("mock topology has issues: %+v", issues)
	}
	if len(data.ServiceInstances) < 15 || len(data.EventTypes) == 0 {
		t.Fatalf("unexpectedly small mock: %d instances, %d event types", len(data.ServiceInstances), len(data.EventTypes))
	}
}

// Decoding and re-encoding the mock must preserve every field: the Go types cover TopologyData v1.
func TestMockTopologyRoundTrips(t *testing.T) {
	data, raw := loadMock(t)
	encoded, err := json.Marshal(data)
	if err != nil {
		t.Fatal(err)
	}
	var a, b any
	if err := json.Unmarshal(raw, &a); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(encoded, &b); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(a, b) {
		t.Fatal("re-encoded mock topology differs from the fixture")
	}
}

func TestStrictDecodingRejectsUnknownFields(t *testing.T) {
	var data domain.TopologyData
	err := fixtures.DecodeStrict([]byte(`{"environments":[],"serviceDefinitions":[],"serviceInstances":[],"resources":[],"relationships":[],"extra":1}`), &data)
	if err == nil {
		t.Fatal("expected unknown field to be rejected")
	}
}
